<?php
require_once __DIR__ . '/../config/security.php';
start_secure_session();
require_once __DIR__ . '/../config/database.php';
require_portal_role($conn, 'dentist', false);
 start_secure_session();require_once '../config/database.php';if(($_SESSION['role']??'')!=='dentist'){header('Location: ../auth/login.php');exit;}$labSettings=clinic_settings($conn);if(($labSettings['laboratory_enabled']??'0')!=='1'){header('Location: dashboard.php');exit;}$uid=(int)$_SESSION['user_id'];$msg='';$type='';if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='save'){ $pid=(int)$_POST['patient_id'];$lab=trim($_POST['laboratory_name']??'');$case=trim($_POST['case_type']??'');$req=$_POST['request_date']??date('Y-m-d');$due=$_POST['due_date']??null;$rel=$_POST['release_date']??null;$status=$_POST['status']??'Pending';$notes=trim($_POST['notes']??'');if($pid&&$lab&&$case){$st=$conn->prepare('INSERT INTO laboratory_cases(patient_id,dentist_id,laboratory_name,case_type,request_date,due_date,release_date,status,notes) VALUES(?,?,?,?,?,?,?,?,?)');$st->bind_param('iisssssss',$pid,$uid,$lab,$case,$req,$due,$rel,$status,$notes);$st->execute();$st->close();$msg='Laboratory request created.';$type='success';log_activity($conn,$uid,'Created laboratory request','Laboratory','Patient ID '.$pid);}}elseif($action==='update'&&$id){$status=$_POST['status'];$due=$_POST['due_date']??null;$rel=$_POST['release_date']??null;$st=$conn->prepare('UPDATE laboratory_cases SET status=?,due_date=?,release_date=? WHERE id=? AND dentist_id=?');$st->bind_param('sssii',$status,$due,$rel,$id,$uid);$st->execute();$st->close();$msg='Laboratory case updated.';$type='success';log_activity($conn,$uid,'Updated laboratory case','Laboratory','Case ID '.$id);}}
$patients=$conn->query("SELECT id,first_name,last_name FROM users WHERE role='patient' AND status='active' ORDER BY last_name,first_name");$cases=$conn->query("SELECT lc.*,CONCAT(u.first_name,' ',u.last_name) patient_name FROM laboratory_cases lc JOIN users u ON u.id=lc.patient_id WHERE lc.dentist_id=$uid ORDER BY lc.created_at DESC");require '../includes/ui.php';ui_header('Laboratory','dentist');ui_sidebar('dentist','laboratory.php');?><div class="page-head"><div><div class="eyebrow">LABORATORY</div><h1>Laboratory Cases</h1><div class="muted">Track prosthesis and other laboratory requests.</div></div></div><?php if($msg)flash($type,$msg);?><section class="card"><h2>New Laboratory Request</h2><form method="post" class="form-grid"><input type="hidden" name="action" value="save"><div class="field"><label>Patient *</label><select name="patient_id" required><option value="">Select patient</option><?php while($p=$patients->fetch_assoc()):?><option value="<?=$p['id']?>"><?=e($p['last_name'].', '.$p['first_name'])?></option><?php endwhile;?></select></div><div class="field"><label>Laboratory *</label><input name="laboratory_name" required></div><div class="field"><label>Case Type *</label><input name="case_type" placeholder="Dentures, crown, etc." required></div><div class="field"><label>Request Date</label><input type="date" name="request_date" value="<?=date('Y-m-d')?>"></div><div class="field"><label>Due Date</label><input type="date" name="due_date"></div><div class="field"><label>Release Date</label><input type="date" name="release_date"></div><div class="field"><label>Status</label><select name="status"><option>Pending</option><option>Sent</option><option>In Progress</option><option>Ready</option><option>Released</option><option>Cancelled</option></select></div><div class="field full"><label>Notes</label><textarea name="notes"></textarea></div><div class="actions full"><button class="btn btn-primary">Send Lab Request</button></div></form></section><section class="card"><h2>Laboratory Cases</h2><div class="table-wrap"><table class="table"><thead><tr><th>Patient</th><th>Case</th><th>Laboratory</th><th>Dates</th><th>Status</th><th>Update</th></tr></thead><tbody><?php while($r=$cases->fetch_assoc()):?><tr><td><?=e($r['patient_name'])?></td><td><?=e($r['case_type'])?><br><span class="muted"><?=e($r['notes'])?></span></td><td><?=e($r['laboratory_name'])?></td><td>Request: <?=e($r['request_date'])?><br>Due: <?=e($r['due_date']?:'—')?><br>Release: <?=e($r['release_date']?:'—')?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><form method="post"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option <?= $r['status']==='Pending'?'selected':''?>>Pending</option><option <?= $r['status']==='Sent'?'selected':''?>>Sent</option><option <?= $r['status']==='In Progress'?'selected':''?>>In Progress</option><option <?= $r['status']==='Ready'?'selected':''?>>Ready</option><option <?= $r['status']==='Released'?'selected':''?>>Released</option><option <?= $r['status']==='Cancelled'?'selected':''?>>Cancelled</option></select><input type="date" name="due_date" value="<?=e($r['due_date']??'')?>"><input type="date" name="release_date" value="<?=e($r['release_date']??'')?>"><button class="btn btn-secondary">Update</button></form></td></tr><?php endwhile;?></tbody></table></div></section><?php ui_footer();?>
